	"go_to_twitter": "ไปที่ x.com",
	"golive__tip_broadcaster_1": "\"<b>เคล็ดลับ:</b> ขอขอบคุณที่ถ่ายทอดสด! ต้อนรับผู้ที่เข้าร่วมชมวิดีโอของคุณด้วยการกล่าว 'สวัสดี'\"",
	"golive__tip_broadcaster_10": "<b>เคล็ดลับ:</b> ขอบคุณที่ถ่ายทอดสดบน X! <3",
	"golive__tip_broadcaster_2": "<b>เคล็ดลับ:</b> ลองเรียกชื่อผู้ชมเมื่อพวกเขาเข้ามาดูวิดีโอถ่ายทอดสดของคุณ พวกเขาจะรู้สึกประทับใจ!",
	"golive__tip_broadcaster_3": "<b>เคล็ดลับ:</b> ออกอากาศอย่างน้อย 2-3 นาทีเพื่อให้ผู้คนพบคุณได้ง่ายขึ้น",
	"golive__tip_broadcaster_4": "<b>เคล็ดลับ:</b> ถามผู้ชมว่าพวกเขามาจากที่ใด ซึ่งถือเป็นวิธีที่ดีในการชวนคุย",
	"golive__tip_broadcaster_5": "<b>เคล็ดลับ:</b> ขอบคุณผู้ชมที่เข้ามาดู และตอบกลับความคิดเห็นของพวกเขาเพื่อให้พวกเขายังคงดูต่อไป",
	"golive__tip_broadcaster_6": "<b>เคล็ดลับ:</b> หากคุณขาดการเชื่อมต่อในระหว่างที่ถ่ายทอดสด ลองไปที่อื่นที่มีสัญญาณดีขึ้น",
	"golive__tip_broadcaster_7": "<b>เคล็ดลับ:</b> ขอให้ผู้ชมติดตามคุณเพื่อให้พวกเขาได้รับการแจ้งเตือนเมื่อคุณถ่ายทอดสดในครั้งต่อไป",
	"golive__tip_broadcaster_8": "<b>เคล็ดลับ:</b> เริ่มต้นวิดีโอถ่ายทอดสดของคุณด้วยการกล่าว “สวัสดี” ทันที ผู้ที่ชมหลังจากนั้นจะชอบ",
	"golive__tip_broadcaster_9": "<b>เคล็ดลับ:</b> ขอบคุณผู้ชมที่เข้ามาดูก่อนที่คุณจะจบวิดีโอถ่ายทอดสดของคุณ",
	"golive__tip_pre_broadcast_1": "<b>เคล็ดลับ:</b>เขียนหัวข้อก่อนที่คุณจะถ่ายทอดสดเพื่อช่วยให้ผู้อื่นค้นพบวิดีโอของคุณ",
	"golive__tip_pre_broadcast_2": "<b>เคล็ดลับ:</b> หัวข้อที่เป็นการอธิบายในตัวจะช่วยให้ผู้คนเข้าใจว่าวิดีโอถ่ายทอดสดของคุณเกี่ยวกับอะไร",
	"golive__tip_pre_broadcast_3": "<b>เคล็ดลับ:</b> ต้องการไอเดียใช่ไหม ลองพาชมสถานที่ แบ่งปันความสามารถพิเศษ หรือพูดคุยเกี่ยวกับหัวข้อที่คุณสนใจ",
	"golive__tip_pre_broadcast_4": "<b>เคล็ดลับ:</b> ตรวจสอบให้แน่ใจว่าคุณมีสัญญาณโทรศัพท์ที่ดีก่อนที่จะถ่ายทอดสด",
	"golive__tip_pre_broadcast_5": "<b>เคล็ดลับ:</b> เพิ่มแฮชแท็กในชื่อเรื่องของคุณเพื่อช่วยให้ผู้อื่นค้นพบวิดีโอถ่ายทอดสดของคุณ",
	"golive__tip_pre_broadcast_6": "<b>เคล็ดลับ:</b> นี่คือเคล็ดลับทั้งหมดของเราสำหรับตอนนี้ ขอบคุณที่ถ่ายทอดสดบน X!",
