	"ps__tip_broadcaster_1": "<b>เคล็ดลับ:</b> ขอขอบคุณที่ออกอากาศ กล่าวทักทายผู้คนที่เข้าร่วมชม",
	"ps__tip_broadcaster_11": "<b>เคล็ดลับ:</b> ขอบคุณที่ออกอากาศบน Periscope",
	"ps__tip_broadcaster_2": "<b>เคล็ดลับ:</b> ลองเรียกชื่อผู้ชมที่เข้ามาดู พวกเขาจะประทับใจมาก",
	"ps__tip_broadcaster_3": "<b>เคล็ดลับ:</b> ออกอากาศอย่างน้อย 2-3 นาทีเพื่อให้ผู้คนพบคุณได้ง่ายขึ้น",
	"ps__tip_broadcaster_4": "<b>เคล็ดลับ:</b> เปิดประเด็นพูดคุยด้วยการถามผู้ชมว่าพวกเขาดูจากที่ไหน",
	"ps__tip_broadcaster_5": "<b>เคล็ดลับ:</b> ขอบคุณผู้ชมที่เข้ามาดู และตอบกลับความคิดเห็นของผู้ชมเพื่อให้ผู้ชมรู้สึกมีส่วนร่วม",
	"ps__tip_broadcaster_6": "<b>เคล็ดลับ:</b>ถ้าคุณสูญเสียการเชื่อมต่อขณะกำลังออกอากาศ โปรดย้ายไปที่อื่นที่มีสัญญาณดีขึ้น",
	"ps__tip_broadcaster_7": "<b>เคล็ดลับ:</b> ขอให้ผู้ชมติดตามคุณ เพื่อรับการแจ้งเตือนเมื่อคุณถ่ายทอดสด",
	"ps__tip_broadcaster_8": "<b>เคล็ดลับ:</b> เริ่มการออกอากาศของคุณโดยกล่าวทักทายทันที ผู้ชมย้อนหลังของคุณจะชอบมาก",
	"ps__tip_broadcaster_9": "<b>เคล็ดลับ:</b> ขอบคุณผู้ชมที่เข้ามาดูก่อนที่คุณจะจบการออกอากาศ",
	"ps__tip_pre_broadcast_1": "<b>เคล็ดลับ:</b>เขียนหัวข้อก่อนเริ่มการออกอากาศของคุณ เพื่อพบกับผู้คนที่มีความสนใจคล้ายๆ คุณ",
	"ps__tip_pre_broadcast_2": "<b>เคล็ดลับ:</b> หัวข้อที่เป็นการอธิบายในตัวจะช่วยให้ผู้คนเข้าใจว่าการออกอากาศของคุณเกี่ยวกับอะไร",
	"ps__tip_pre_broadcast_3": "<b>เคล็ดลับ:</b> ต้องการไอเดียใช่ไหม ลองพาชมสถานที่ แบ่งปันความสามารถพิเศษ หรือพูดคุยเกี่ยวกับหัวข้อที่คุณสนใจ",
	"ps__tip_pre_broadcast_4": "<b>เคล็ดลับ:</b> ตรวจสอบให้แน่ใจว่าสัญญาณโทรศัพท์ของคุณแรงพอก่อนจะถ่ายทอดสด",
	"ps__tip_pre_broadcast_5": "<b>เคล็ดลับ:</b> แชร์การออกอากาศของคุณบน X เพื่อเข้าถึงผู้ชมมากขึ้น",
	"ps__tip_pre_broadcast_6": "<b>เคล็ดลับ:</b> ถ้าคุณติดตามคนที่ติดตามคุณ คุณจะสามารถออกอากาศให้กับเขาเป็นการส่วนตัว",
	"ps__tip_pre_broadcast_8": "<b>เคล็ดลับ:</b> เพิ่มแฮชแท็กที่เกี่ยวข้องในชื่อเรื่องของคุณ เพื่อให้ผู้คนพบการออกอากาศของคุณ",
	"ps__tip_pre_broadcast_9": "<b>เคล็ดลับ:</b> นี่คือเคล็ดลับทั้งหมดของเราสำหรับตอนนี้ ขอขอบคุณที่ใช้ Periscope",
	"ps__tip_viewer_1": "<b>เคล็ดลับ:</b> คุณเป็นคนแรกๆ ที่เข้าร่วม เขียนความคิดเห็นแล้วกล่าวทักทายเลย",
	"ps__tip_viewer_2": "<b>เคล็ดลับ:</b> เขียนความคิดเห็น และบอกให้ <b>%1$s</b> รู้ว่าคุณอยู่ที่นี่",
	"ps__tip_viewer_3": "<b>เคล็ดลับ:</b>บอกให้ <b>%1$s</b> รู้ว่าคุณกำลังดูจากที่ไหน",
	"ps__tip_viewer_4": "<b>เคล็ดลับ:</b> กล่าวทักทายเพื่อแชทกับ <b>%1$s</b> และผู้ชมคนอื่นๆ",
	"ps__toast_broadcast_notify_followers": "เราได้อนุญาตให้ผู้ติดตามรู้ว่าคุณเข้าร่วมเป็นแขกรับเชิญ",
